-- Generated by scripts/seed-addis-vendors.mjs from kiburan_addis_ababa_vendor_test_data.json
-- Local marketplace seed only. Do not treat prices or verification as production truth.
begin;

-- Extra categories used by the Addis dataset
insert into public.vendor_categories (slug, name_en, name_am) values
  ('attire', 'Traditional attire', null),
  ('invitations', 'Invitations & printing', null),
  ('coffee', 'Coffee ceremony', null)
on conflict (slug) do update set name_en = excluded.name_en;

-- Ensure seed owner exists (same id as seed.sql)
do $$
declare
  v_owner uuid := '11111111-1111-4111-8111-111111111111';
begin
  if not exists (select 1 from auth.users where id = v_owner) then
    insert into auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) values (
      '00000000-0000-0000-0000-000000000000', v_owner, 'authenticated', 'authenticated',
      'marketplace.seed@kiburan.local', crypt('SeedVendorPass1', gen_salt('bf')), now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      '{"display_name":"Marketplace Seed Owner"}'::jsonb, now(), now(), '', '', '', ''
    );
    insert into auth.identities (
      id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at
    ) values (
      v_owner, v_owner,
      format('{"sub":"%s","email":"marketplace.seed@kiburan.local"}', v_owner)::jsonb,
      'email', v_owner::text, now(), now(), now()
    ) on conflict do nothing;
  end if;
  insert into public.profiles (id, display_name)
  values (v_owner, 'Marketplace Seed Owner')
  on conflict (id) do update set display_name = coalesce(nullif(public.profiles.display_name, ''), excluded.display_name);
end $$;

-- Remove previous seed marketplace vendors.
-- wedding_vendors / inquiries cannot rely on ON DELETE SET NULL when both
-- vendor_id and external_business_name would become null.
with seed_vendors as (
  select id from public.vendors
  where owner_user_id = '11111111-1111-4111-8111-111111111111'
     or id in (
       '22222222-2222-4222-8222-222222222221',
       '22222222-2222-4222-8222-222222222222',
       '22222222-2222-4222-8222-222222222223',
       '22222222-2222-4222-8222-222222222224'
     )
)
delete from public.wedding_vendors wv
using seed_vendors s where wv.vendor_id = s.id;

with seed_vendors as (
  select id from public.vendors
  where owner_user_id = '11111111-1111-4111-8111-111111111111'
     or id in (
       '22222222-2222-4222-8222-222222222221',
       '22222222-2222-4222-8222-222222222222',
       '22222222-2222-4222-8222-222222222223',
       '22222222-2222-4222-8222-222222222224'
     )
)
delete from public.vendor_inquiries vi
using seed_vendors s where vi.vendor_id = s.id;

delete from public.vendors
where owner_user_id = '11111111-1111-4111-8111-111111111111'
   or id in (
     '22222222-2222-4222-8222-222222222221',
     '22222222-2222-4222-8222-222222222222',
     '22222222-2222-4222-8222-222222222223',
     '22222222-2222-4222-8222-222222222224'
   );

